CREATE TABLE stream_guest_stage(broadcast_id text PRIMARY KEY REFERENCES broadcast_run(id),stream_id text NOT NULL REFERENCES streaming_stream(id),room_id text NOT NULL REFERENCES room(id),enabled boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,max_guests integer NOT NULL CHECK(max_guests BETWEEN 1 AND 3),layout text NOT NULL DEFAULT 'grid' CHECK(layout IN ('single','grid','pip')));
CREATE INDEX guest_stage_stream_idx ON stream_guest_stage(stream_id);
CREATE UNIQUE INDEX guest_stage_room_active_idx ON stream_guest_stage(room_id) WHERE enabled;
CREATE TABLE stream_audience(id text PRIMARY KEY,broadcast_id text NOT NULL REFERENCES stream_guest_stage(broadcast_id),subject text NOT NULL,name text NOT NULL,role text NOT NULL CHECK(role IN ('host','cohost','moderator','guest','viewer')),delegations jsonb NOT NULL DEFAULT '[]',epoch integer NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL DEFAULT now()+interval '1 hour',UNIQUE(broadcast_id,subject));
CREATE TABLE stream_guest(id text PRIMARY KEY,broadcast_id text NOT NULL REFERENCES stream_guest_stage(broadcast_id),subject text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('invite','request')),state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','declined','approved','rejected','cancelled','expired','joined','left','removed')),media jsonb NOT NULL,muted_audio boolean NOT NULL DEFAULT false,muted_video boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,participant_id text UNIQUE,actor_id text NOT NULL,decided_by text,event_sequence integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,last_joined_at timestamptz);
CREATE INDEX guest_run_created_idx ON stream_guest(broadcast_id,id DESC);
CREATE INDEX guest_expiry_idx ON stream_guest(state,expires_at);
CREATE UNIQUE INDEX guest_subject_open_idx ON stream_guest(broadcast_id,subject) WHERE state IN ('pending','accepted','approved','joined');
CREATE TABLE stream_guest_grant(token_id text PRIMARY KEY,guest_id text NOT NULL REFERENCES stream_guest(id),participant_id text NOT NULL,version integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX guest_grant_expiry_idx ON stream_guest_grant(expires_at);
ALTER TABLE streaming_session ADD COLUMN guest_stage boolean NOT NULL DEFAULT false;
CREATE FUNCTION guest_participant_authorized(pid text) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT left(pid,7)<>'guestp_' OR EXISTS(
 SELECT 1 FROM stream_guest g JOIN stream_guest_stage st ON st.broadcast_id=g.broadcast_id JOIN broadcast_run b ON b.id=st.broadcast_id JOIN streaming_stream t ON t.id=st.stream_id JOIN project p ON p.id=t.project_id JOIN environment e ON e.id=t.environment_id JOIN organization o ON o.id=t.organization_id JOIN room r ON r.id=st.room_id
 WHERE g.participant_id=pid AND g.state IN ('accepted','approved','joined') AND g.expires_at>now() AND st.enabled AND b.desired_state='running' AND b.state NOT IN ('stopping','stopped','failed') AND t.source->>'kind'='room' AND t.source->>'roomId'=st.room_id AND t.status='active' AND p.status='active' AND e.status='active' AND o.status='active' AND r.status IN ('created','active')
 AND EXISTS(SELECT 1 FROM stream_guest_grant gg WHERE gg.guest_id=g.id AND gg.participant_id=pid AND gg.version=g.version AND gg.expires_at>now())); $$;
CREATE FUNCTION guest_token_authorized(pid text,tid text) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT left(pid,7)<>'guestp_' OR (guest_participant_authorized(pid) AND EXISTS(SELECT 1 FROM stream_guest_grant gg JOIN stream_guest g ON g.id=gg.guest_id WHERE gg.token_id=tid AND gg.participant_id=pid AND g.participant_id=pid AND gg.version=g.version AND gg.expires_at>now())); $$;
CREATE FUNCTION guest_session_authorized(sid text,permission text DEFAULT '') RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT EXISTS(SELECT 1 FROM participant_session ps JOIN participant pt ON pt.id=ps.participant_id LEFT JOIN stream_guest g ON g.participant_id=pt.id WHERE ps.id=sid AND pt.left_at IS NULL AND ps.connection_state IN ('connected','reconnecting') AND guest_participant_authorized(pt.id) AND (left(pt.id,7)<>'guestp_' OR permission='' OR (permission='audio' AND (g.media->>'audio')::boolean AND NOT g.muted_audio) OR (permission='camera_video' AND (g.media->>'video')::boolean AND NOT g.muted_video) OR (permission IN ('screen_audio','screen_video') AND (g.media->>'screen')::boolean AND NOT g.muted_video AND (permission<>'screen_audio' OR NOT g.muted_audio)))); $$;
CREATE FUNCTION revoke_stream_guest_participant() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.participant_id IS NOT NULL AND (NEW.version<>OLD.version OR NEW.state IN ('left','removed','expired','cancelled')) THEN UPDATE participant SET removed_at=coalesce(removed_at,now()) WHERE id=OLD.participant_id AND removed_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER stream_guest_revocation AFTER UPDATE ON stream_guest FOR EACH ROW EXECUTE FUNCTION revoke_stream_guest_participant();
CREATE FUNCTION reserve_guest_room_capacity() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE maximum integer; occupied integer; reserved integer; BEGIN
 IF left(NEW.id,7)='guestp_' AND NOT guest_participant_authorized(NEW.id) THEN RAISE EXCEPTION 'Guest grant revoked'; END IF;
 IF NOT EXISTS(SELECT 1 FROM stream_guest_stage WHERE room_id=NEW.room_id AND enabled) THEN RETURN NEW; END IF;
 SELECT max_participants INTO maximum FROM room WHERE id=NEW.room_id FOR UPDATE;
 SELECT count(*) INTO occupied FROM participant WHERE room_id=NEW.room_id AND left_at IS NULL;
 SELECT count(*) INTO reserved FROM stream_guest g JOIN stream_guest_stage st ON st.broadcast_id=g.broadcast_id WHERE st.room_id=NEW.room_id AND st.enabled AND g.state IN ('accepted','approved','joined') AND g.expires_at>now() AND g.participant_id IS DISTINCT FROM NEW.id AND NOT EXISTS(SELECT 1 FROM participant p WHERE p.id=g.participant_id AND p.left_at IS NULL);
 IF occupied+reserved>=maximum THEN RAISE EXCEPTION 'Guest stage capacity is reserved'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guest_room_capacity_guard BEFORE INSERT ON participant FOR EACH ROW EXECUTE FUNCTION reserve_guest_room_capacity();

ALTER TABLE webhook_event DROP CONSTRAINT webhook_event_type_check;
ALTER TABLE webhook_event ADD CONSTRAINT webhook_event_type_check CHECK(event_type IN ('room.created', 'room.started', 'room.ended', 'participant.joined', 'participant.left', 'participant.reconnected', 'track.published', 'track.unpublished', 'connection.degraded', 'connection.recovered', 'stream.created', 'stream.starting', 'stream.live', 'stream.reconnecting', 'stream.ended', 'stream.failed', 'broadcast.created', 'broadcast.starting', 'broadcast.live', 'broadcast.reconnecting', 'broadcast.output_degraded', 'broadcast.stopped', 'broadcast.failed', 'destination.created', 'destination.connected', 'destination.disconnected', 'destination.retrying', 'destination.failed', 'recording.started', 'recording.segment_committed', 'recording.finalizing', 'recording.ready', 'recording.failed', 'recording.deleted', 'schedule.created','schedule.updated','schedule.starting','schedule.started','schedule.missed','schedule.cancelled','schedule.failed','schedule.completed','schedule.reminder','restream.probing','restream.source_connected','restream.source_lost','restream.recovering','restream.stopped','restream.failed','clip.requested','clip.rendering','clip.ready','clip.failed','clip.deleted','mixer.started','mixer.scene_activated','mixer.source_lost','mixer.overloaded','mixer.stopped','mixer.failed','dvr.enabled','dvr.window_changed','dvr.segment_evicted','dvr.disabled','stream.guest.invited','stream.guest.invite_accepted','stream.guest.invite_declined','stream.guest.requested','stream.guest.request_approved','stream.guest.request_rejected','stream.guest.joined','stream.guest.left','stream.guest.removed','stream.guest.muted','stream.guest.invite_expired','stream.guest.invite_cancelled','stream.guest.grant_revoked'));
ALTER TABLE webhook_endpoint DROP CONSTRAINT webhook_endpoint_event_types_check;
ALTER TABLE webhook_endpoint ADD CONSTRAINT webhook_endpoint_event_types_check CHECK(cardinality(event_types) BETWEEN 1 AND 77 AND array_position(event_types,NULL) IS NULL AND event_types <@ ARRAY['room.created', 'room.started', 'room.ended', 'participant.joined', 'participant.left', 'participant.reconnected', 'track.published', 'track.unpublished', 'connection.degraded', 'connection.recovered', 'stream.created', 'stream.starting', 'stream.live', 'stream.reconnecting', 'stream.ended', 'stream.failed', 'broadcast.created', 'broadcast.starting', 'broadcast.live', 'broadcast.reconnecting', 'broadcast.output_degraded', 'broadcast.stopped', 'broadcast.failed', 'destination.created', 'destination.connected', 'destination.disconnected', 'destination.retrying', 'destination.failed', 'recording.started', 'recording.segment_committed', 'recording.finalizing', 'recording.ready', 'recording.failed', 'recording.deleted', 'schedule.created','schedule.updated','schedule.starting','schedule.started','schedule.missed','schedule.cancelled','schedule.failed','schedule.completed','schedule.reminder','restream.probing','restream.source_connected','restream.source_lost','restream.recovering','restream.stopped','restream.failed','clip.requested','clip.rendering','clip.ready','clip.failed','clip.deleted','mixer.started','mixer.scene_activated','mixer.source_lost','mixer.overloaded','mixer.stopped','mixer.failed','dvr.enabled','dvr.window_changed','dvr.segment_evicted','dvr.disabled','stream.guest.invited','stream.guest.invite_accepted','stream.guest.invite_declined','stream.guest.requested','stream.guest.request_approved','stream.guest.request_rejected','stream.guest.joined','stream.guest.left','stream.guest.removed','stream.guest.muted','stream.guest.invite_expired','stream.guest.invite_cancelled','stream.guest.grant_revoked']::text[]);




CREATE INDEX audience_expiry_idx ON stream_audience(expires_at);
CREATE FUNCTION guest_stage_disable_fence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.enabled AND NOT NEW.enabled THEN UPDATE stream_guest SET version=version+1,expires_at=least(expires_at,now()) WHERE broadcast_id=NEW.broadcast_id AND state IN ('pending','accepted','approved','joined'); END IF; RETURN NEW; END $$;
CREATE TRIGGER guest_stage_disable_fence AFTER UPDATE OF enabled ON stream_guest_stage FOR EACH ROW EXECUTE FUNCTION guest_stage_disable_fence();
CREATE FUNCTION validate_guest_stage_parent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM broadcast_run b JOIN streaming_stream s ON s.id=b.stream_id JOIN room r ON r.id=NEW.room_id WHERE b.id=NEW.broadcast_id AND s.id=NEW.stream_id AND s.source->>'kind'='room' AND s.source->>'roomId'=r.id AND r.project_id=s.project_id AND r.environment_id=s.environment_id) THEN RAISE EXCEPTION 'Invalid guest stage scope'; END IF;RETURN NEW;END $$;
CREATE TRIGGER guest_stage_parent_guard BEFORE INSERT OR UPDATE OF broadcast_id,stream_id,room_id ON stream_guest_stage FOR EACH ROW EXECUTE FUNCTION validate_guest_stage_parent();

CREATE INDEX guest_grant_guest_idx ON stream_guest_grant(guest_id,version,expires_at);
